<template>
  <section class="local-assistant">
    <header><div><h2>Local assistant</h2><p>Research, create and review using one installed model. Your selected material stays on this device.</p></div><button class="usx-btn" :disabled="busy" @click="load"><UIcon name="refresh" />Check models</button></header>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
    <p v-if="!online">Ollama is unavailable. Start it from Server, or install it from the <a href="https://ollama.com/download" target="_blank" rel="noopener noreferrer">official site</a>.</p>
    <form @submit.prevent="run">
      <label for="assistant-purpose">I want to</label><select id="assistant-purpose" v-model="purpose"><option value="project">Advance a project</option><option value="knowledge">Curate personal knowledge</option><option value="creative">Create something</option><option value="ucode">Write uCode</option></select>
      <label for="assistant-model">Installed local model</label><select id="assistant-model" v-model="model"><option value="">Choose a model</option><option v-for="item in chatModels" :key="item.name" :value="item.name">{{ item.name }}</option></select>
      <label for="assistant-goal">What would you like to achieve?</label><input id="assistant-goal" v-model="goal" maxlength="1000" required />
      <label for="assistant-material">Selected notes and sources</label><textarea id="assistant-material" v-model="material" maxlength="12000" rows="6" placeholder="Paste relevant notes, including source names or links. Nothing is fetched automatically." />
      <p>Researcher → Creator → Reviewer. This is a draft preview, not independent fact verification. It does not browse, execute code or change your knowledge baseline.</p>
      <button class="usx-btn usx-btn--primary" :disabled="busy||!online||!model||!goal.trim()"><UIcon name="auto_awesome" />{{ busy?'Working…':'Create a draft' }}</button>
    </form>
    <section v-if="result"><h3>Draft</h3><pre>{{ result.content }}</pre><button class="usx-btn" @click="download"><UIcon name="download" />Save Markdown copy</button><details><summary>Roundtable notes</summary><article v-for="output in result.outputs" :key="output.role"><h4>{{ output.name }}</h4><pre>{{ output.content }}</pre></article></details><p>Save accepted work in your Vault or Shared layer. Global Knowledge remains unchanged.</p></section>
    <details><summary>Installed model library · {{ models.length }}</summary><p>Models are discovered from Ollama. Coding-focused models are preserved until their dependencies and usefulness are reviewed.</p><article v-for="item in models" :key="item.name"><strong>{{ item.name }}</strong><span>{{ (item.size/1e9).toFixed(2) }} GB{{ item.coding_focused?' · coding focused':'' }}{{ !item.local_chat?' · search/embedding or remote-only':'' }}</span></article></details>
    <details><summary>Install an offline model</summary><p>Reviewed application packs will specify their model needs. For now, choose an explicit tagged model from the official library. Downloading does not make it a reviewed uDOS pack.</p><a href="https://ollama.com/library" target="_blank" rel="noopener noreferrer">Browse the official library</a><label for="model-reference">Official model reference</label><input id="model-reference" v-model="downloadModel" placeholder="model:tag" /><button class="usx-btn" :disabled="busy||!online||!downloadModel.trim()" @click="pull">Download selected model</button><p>Check its licence, download size and device requirements first. Existing models are not deleted. Keep this view open for progress; disconnecting does not guarantee Ollama cancels its download.</p></details>
  </section>
</template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {UCORE_BASE} from '../../../api/base';
import UIcon from '../../../skills/atoms/UIcon.vue';
const models=ref<any[]>([]),online=ref(false),busy=ref(false),error=ref(''),message=ref(''),model=ref(''),purpose=ref('project'),goal=ref(''),material=ref(''),downloadModel=ref(''),result=ref<any>(null);
const chatModels=computed(()=>models.value.filter(item=>item.local_chat));
async function load(){error.value='';try{const response=await fetch(`${UCORE_BASE}/api/assistant/library`);const data=await response.json();online.value=!!data.online;models.value=data.models||[];if(!response.ok)throw Error(data.error||'Local assistant unavailable');}catch(e){online.value=false;error.value=e instanceof Error?e.message:'Could not load models';}}
async function run(){busy.value=true;error.value='';result.value=null;try{const response=await fetch(`${UCORE_BASE}/api/assistant/roundtable`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({goal:goal.value,material:material.value,model:model.value,purpose:purpose.value})});if(!response.ok)throw Error((await response.text()).slice(0,240));result.value=await response.json();}catch(e){error.value=e instanceof Error?e.message:'Draft unavailable';}finally{busy.value=false;}}
async function pull(){if(!window.confirm(`Download ${downloadModel.value} from the official Ollama library? This uses internet data and local disk space. Review its licence and requirements first.`))return;busy.value=true;error.value='';message.value='Starting download…';try{const response=await fetch(`${UCORE_BASE}/api/assistant/models/pull`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:downloadModel.value,confirm:true})});if(!response.ok||!response.body)throw Error((await response.text()).slice(0,240));const reader=response.body.getReader(),decoder=new TextDecoder();let pending='',success=false;while(true){const {done,value}=await reader.read();pending+=decoder.decode(value,{stream:!done});const lines=pending.split('\n');pending=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.error)throw Error(event.error);message.value=event.status+(event.total?` · ${Math.round(100*(event.completed||0)/event.total)}%`:'');if(event.status==='success')success=true;}if(done)break;}if(!success)throw Error('Download ended without a verified success response. Check installed models before retrying.');await load();message.value='Model downloaded. Choose it above to try a local draft.';}catch(e){error.value=e instanceof Error?e.message:'Download failed';}finally{busy.value=false;}}
function download(){const url=URL.createObjectURL(new Blob([result.value.content],{type:'text/markdown'}));const link=document.createElement('a');link.href=url;link.download=purpose.value==='ucode'?'ucode-draft.md':'roundtable-draft.md';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
onMounted(load);
</script>
<style scoped>
.local-assistant{display:grid;gap:16px;text-align:left;max-width:64rem;margin:auto}.local-assistant header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.local-assistant header>div{flex:1}.local-assistant h2,.local-assistant h3,.local-assistant h4,.local-assistant p{margin:0 0 8px}.local-assistant p{font-size:var(--usx-font-size-sm);color:var(--usx-color-on-surface-muted)}form{display:grid;gap:8px}label{margin:0}input,select,textarea{box-sizing:border-box;width:100%;font:inherit;padding:8px;border:1px solid var(--usx-color-border);border-radius:var(--usx-radius-sm);background:var(--usx-color-surface);color:inherit;box-shadow:none}input,select{height:36px}.usx-btn{display:inline-flex;align-items:center;gap:6px;width:fit-content;min-height:32px;padding:4px 10px;margin:0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.6}article{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;padding:8px 0;border-bottom:1px solid var(--usx-color-border)}details{padding:12px 0;border-top:1px solid var(--usx-color-border)}summary{cursor:pointer;margin-bottom:8px}[role=alert]{color:var(--usx-color-danger)}
</style>
